import numba, numpy as np, time
from numba import njit
from scipy.optimize import linear_sum_assignment

@njit(cache=True)
def hungarian(cost):
    n = cost.shape[0]
    u = np.zeros(n+1)
    v = np.zeros(n+1)
    p = np.zeros(n+1, dtype=np.int64)
    way = np.zeros(n+1, dtype=np.int64)
    INF = 1e100
    for i in range(1, n+1):
        p[0] = i
        j0 = 0
        minv = np.empty(n+1)
        for j in range(n+1):
            minv[j] = INF
        used = np.zeros(n+1, dtype=np.bool_)
        while True:
            used[j0] = True
            i0 = p[j0]
            delta = INF
            j1 = 0
            for j in range(1, n+1):
                if not used[j]:
                    cur = cost[i0-1, j-1] - u[i0] - v[j]
                    if cur < minv[j]:
                        minv[j] = cur
                        way[j] = j0
                    if minv[j] < delta:
                        delta = minv[j]
                        j1 = j
            for j in range(n+1):
                if used[j]:
                    u[p[j]] += delta
                    v[j] -= delta
                else:
                    minv[j] -= delta
            j0 = j1
            if p[j0] == 0:
                break
        while True:
            j1 = way[j0]
            p[j0] = p[j1]
            j0 = j1
            if j0 == 0:
                break
    cols = np.empty(n, dtype=np.int64)
    for j in range(1, n+1):
        cols[p[j]-1] = j-1
    return cols

np.random.seed(0)
for n in [100, 300, 600]:
    M=np.random.rand(n,n)
    t0=time.perf_counter(); c=hungarian(M); t1=time.perf_counter()-t0
    t0=time.perf_counter(); c=hungarian(M); t2=time.perf_counter()-t0
    r,cs=linear_sum_assignment(M)
    print(n, 'compile+run', t1, 'run', t2, 'match', np.array_equal(c, cs), 'cost_h', M[np.arange(n),c].sum(), 'cost_s', M[r,cs].sum())
