import numpy as np, time
from numba import njit

N=1201
@njit
def scan_children(parent, in_sub, reps):
    s=0
    for r in range(reps):
        for node in range(N):
            if in_sub[node]:
                s += parent[node]
    return s

parent=np.arange(N)
in_sub=np.zeros(N, np.int8)
in_sub[:30]=1
scan_children(parent, in_sub, 1)
t0=time.perf_counter(); scan_children(parent, in_sub, 5000); print('5k scans', time.perf_counter()-t0)

@njit
def find_pred(thread, target, reps):
    N=thread.shape[0]
    s=0
    for r in range(reps):
        node=0
        for _ in range(N):
            if thread[node]==target:
                s+=node
                break
            node=thread[node]
    return s
thread=np.arange(1,N+1)%N
find_pred(thread, 100, 1)
t0=time.perf_counter(); find_pred(thread, 600, 5000); print('5k pred scans', time.perf_counter()-t0)
