// Bipartite transportation network simplex.
// Nodes: sources 0..n-1, sinks n..n+m-1, root n+m.
// Compile: c++ -O3 -std=c++17 -shared -fPIC simplex.cpp -o libsimplex.so
#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstring>
#include <limits>

struct Result {
    int iters;
    double art_flow;
};

// Solve. edge_i/edge_j/edge_c length E. flow_out length E.
extern "C" Result solve_ot(const double* a, const double* b, int n, int m,
                           const int* edge_i, const int* edge_j, const double* edge_c, int E,
                           double* flow_out, int max_iter) {
    const int root = n + m;
    const int N = n + m + 1;
    const int Ereal = E;
    const int ET = Ereal + n + m; // total edges

    std::vector<int> tail(ET), hed(ET);
    std::vector<double> cost(ET), flow(ET, 0.0);
    const double BIG = 1e6;
    for (int e = 0; e < Ereal; ++e) {
        tail[e] = edge_i[e];
        hed[e] = n + edge_j[e];
        cost[e] = edge_c[e];
    }
    for (int i = 0; i < n; ++i) {
        int e = Ereal + i;
        tail[e] = i; hed[e] = root; cost[e] = BIG;
    }
    for (int j = 0; j < m; ++j) {
        int e = Ereal + n + j;
        tail[e] = root; hed[e] = n + j; cost[e] = BIG;
    }

    std::vector<int> parent(N), parent_edge(N), depth(N), thread(N), to_parent(N);
    std::vector<double> pi(N, 0.0);

    parent[root] = -1; parent_edge[root] = -1; depth[root] = 0; to_parent[root] = 0; pi[root] = 0.0;
    for (int i = 0; i < n; ++i) {
        parent[i] = root; parent_edge[i] = Ereal + i; depth[i] = 1; to_parent[i] = 1;
        flow[Ereal + i] = a[i]; pi[i] = BIG;
    }
    for (int j = 0; j < m; ++j) {
        int node = n + j;
        parent[node] = root; parent_edge[node] = Ereal + n + j; depth[node] = 1; to_parent[node] = -1;
        flow[Ereal + n + j] = b[j]; pi[node] = -BIG;
    }
    thread[root] = 0;
    for (int node = 0; node < N - 2; ++node) thread[node] = node + 1;
    thread[N - 2] = root;

    // predecessor in thread for O(1) unlink: maintain revthread
    std::vector<int> revthread(N);
    for (int node = 0; node < N; ++node) revthread[thread[node]] = node;

    auto pi_from_parent = [&](int node) {
        int p = parent[node];
        int e = parent_edge[node];
        if (to_parent[node] == 1) return pi[p] + cost[e];
        else return pi[p] - cost[e];
    };

    int block = (int)std::sqrt((double)Ereal) + 1;
    if (block < 16) block = 16;
    int next_start = 0;
    int iters = 0;
    const double tol = 1e-12;

    std::vector<int> sub_nodes(N);
    std::vector<int> path(N);
    std::vector<int> old_pedge(N), old_topar(N);
    std::vector<int> child_head(N), child_next(N);
    std::vector<int> order(N), stack(N), tmp(N);
    std::vector<char> in_sub(N);

    for (int it = 0; it < max_iter; ++it) {
        iters = it;
        double best = -tol;
        int enter = -1;
        int scanned = 0;
        int e = next_start;
        while (scanned < Ereal) {
            double red = cost[e] - pi[tail[e]] + pi[hed[e]];
            if (red < best) { best = red; enter = e; }
            ++scanned;
            if (enter >= 0 && (scanned % block) == 0) break;
            ++e;
            if (e == Ereal) e = 0;
        }
        next_start = e + 1;
        if (next_start >= Ereal) next_start = 0;
        if (enter < 0) break;

        int u = tail[enter];
        int v = hed[enter];
        int uu = u, vv = v;
        while (depth[uu] > depth[vv]) uu = parent[uu];
        while (depth[vv] > depth[uu]) vv = parent[vv];
        while (uu != vv) { uu = parent[uu]; vv = parent[vv]; }
        int apex = uu;

        double INF = 1e100;
        double delta = INF;
        int leave = -1, leave_node = -1, leave_side = -1;
        for (int node = u; node != apex; node = parent[node]) {
            int pe = parent_edge[node];
            if (to_parent[node] == 1 && flow[pe] < delta) {
                delta = flow[pe]; leave = pe; leave_node = node; leave_side = 0;
            }
        }
        for (int node = v; node != apex; node = parent[node]) {
            int pe = parent_edge[node];
            if (to_parent[node] == -1 && flow[pe] <= delta) {
                delta = flow[pe]; leave = pe; leave_node = node; leave_side = 1;
            }
        }
        if (leave < 0) break;

        flow[enter] += delta;
        for (int node = u; node != apex; node = parent[node]) {
            int pe = parent_edge[node];
            if (to_parent[node] == 1) flow[pe] -= delta; else flow[pe] += delta;
        }
        for (int node = v; node != apex; node = parent[node]) {
            int pe = parent_edge[node];
            if (to_parent[node] == -1) flow[pe] -= delta; else flow[pe] += delta;
        }

        // pivot
        int new_parent, new_root, new_to_parent;
        if (leave_side == 0) { new_parent = v; new_root = u; new_to_parent = 1; }
        else { new_parent = u; new_root = v; new_to_parent = -1; }

        int sub_count = 0;
        sub_nodes[sub_count++] = leave_node;
        for (int node = thread[leave_node]; depth[node] > depth[leave_node]; node = thread[node])
            sub_nodes[sub_count++] = node;
        int subtree_end_next = thread[sub_nodes[sub_count - 1]];

        // unlink
        int pred = revthread[leave_node];
        thread[pred] = subtree_end_next;
        revthread[subtree_end_next] = pred;

        // path new_root -> leave_node
        int path_len = 0;
        for (int node = new_root; ; node = parent[node]) {
            path[path_len++] = node;
            if (node == leave_node) break;
        }
        for (int t = 0; t < path_len; ++t) {
            old_pedge[t] = parent_edge[path[t]];
            old_topar[t] = to_parent[path[t]];
        }
        parent[new_root] = new_parent;
        parent_edge[new_root] = enter;
        to_parent[new_root] = new_to_parent;
        for (int t = 1; t < path_len; ++t) {
            parent[path[t]] = path[t - 1];
            parent_edge[path[t]] = old_pedge[t - 1];
            to_parent[path[t]] = (old_topar[t - 1] == 1) ? -1 : 1;
        }

        std::memset(child_head.data(), 0xFF, N * sizeof(int));
        for (int t = 0; t < sub_count; ++t) {
            int node = sub_nodes[t];
            if (node != new_root) {
                int p = parent[node];
                child_next[node] = child_head[p];
                child_head[p] = node;
            }
        }
        pi[new_root] = pi_from_parent(new_root);
        depth[new_root] = depth[new_parent] + 1;

        int sptr = 0, idx = 0;
        stack[sptr++] = new_root;
        while (sptr) {
            int node = stack[--sptr];
            order[idx++] = node;
            int ccount = 0;
            for (int c = child_head[node]; c >= 0; c = child_next[c]) tmp[ccount++] = c;
            for (int t = 0; t < ccount; ++t) {
                int c = tmp[t];
                depth[c] = depth[node] + 1;
                pi[c] = pi_from_parent(c);
            }
            for (int t = ccount - 1; t >= 0; --t) stack[sptr++] = tmp[t];
        }

        // splice after new_parent
        int old_next = thread[new_parent];
        thread[new_parent] = order[0];
        revthread[order[0]] = new_parent;
        for (int t = 0; t < sub_count - 1; ++t) {
            thread[order[t]] = order[t + 1];
            revthread[order[t + 1]] = order[t];
        }
        thread[order[sub_count - 1]] = old_next;
        revthread[old_next] = order[sub_count - 1];
        ++iters;
    }

    double art = 0;
    for (int e = Ereal; e < ET; ++e) art += flow[e];
    std::memcpy(flow_out, flow.data(), Ereal * sizeof(double));
    Result r; r.iters = iters; r.art_flow = art;
    return r;
}
