#include <cstdint>
#include <vector>
#include <cmath>
#include <cstring>
#include <algorithm>

struct Result { int iters; double art_flow; };

extern "C" Result solve_ot(const double* a, const double* b, int n, int m,
                           const int* edge_i, const int* edge_j, const double* edge_c, int E,
                           double* flow_out, int max_iter) {
    const int root = n + m;
    const int N = n + m + 1;
    const int Ereal = E;
    const int ET = Ereal + n + m;
    const double BIG = 1e6;
    const double tol = 1e-12;

    std::vector<int> tail(ET), hed(ET);
    std::vector<double> cost(ET), flow(ET, 0.0);
    for (int e = 0; e < Ereal; ++e) {
        tail[e] = edge_i[e];
        hed[e] = n + edge_j[e];
        cost[e] = edge_c[e];
    }
    for (int i = 0; i < n; ++i) {
        int e = Ereal + i;
        tail[e] = i; hed[e] = root; cost[e] = BIG; flow[e] = a[i];
    }
    for (int j = 0; j < m; ++j) {
        int e = Ereal + n + j;
        tail[e] = root; hed[e] = n + j; cost[e] = BIG; flow[e] = b[j];
    }

    std::vector<int> parent(N), pedge(N), depth(N), thread(N), rev(N), to_parent(N);
    std::vector<double> pi(N);

    parent[root] = -1; pedge[root] = -1; depth[root] = 0; to_parent[root] = 0; pi[root] = 0;
    for (int i = 0; i < n; ++i) {
        parent[i] = root; pedge[i] = Ereal + i; depth[i] = 1; to_parent[i] = 1; pi[i] = BIG;
    }
    for (int j = 0; j < m; ++j) {
        int node = n + j;
        parent[node] = root; pedge[node] = Ereal + n + j; depth[node] = 1; to_parent[node] = -1; pi[node] = -BIG;
    }
    thread[root] = 0;
    for (int i = 0; i < N - 2; ++i) thread[i] = i + 1;
    thread[N - 2] = root;
    for (int i = 0; i < N; ++i) rev[thread[i]] = i;

    // children adjacency for initial tree (all children of root) not needed

    int next_start = 0;
    int iters = 0;

    std::vector<int> path(N), old_pe(N), old_tp(N);
    std::vector<int> child_head(N), child_next(N), order(N), stackv(N);

    auto piv = [&](int enter, int u, int v, int leave_node, int leave_side) {
        int new_parent, new_root, new_tp;
        if (leave_side == 0) { new_parent = v; new_root = u; new_tp = 1; }
        else { new_parent = u; new_root = v; new_tp = -1; }

        // subtree nodes in preorder, and unlink
        int leave_depth = depth[leave_node];
        int sub_count = 0;
        // We'll rebuild thread after; collect nodes
        // Use order buffer temporarily
        order[sub_count++] = leave_node;
        for (int node = thread[leave_node]; depth[node] > leave_depth; node = thread[node])
            order[sub_count++] = node;
        int after = thread[order[sub_count - 1]];
        int pred = rev[leave_node];
        thread[pred] = after;
        rev[after] = pred;

        int path_len = 0;
        for (int node = new_root; ; node = parent[node]) {
            path[path_len] = node;
            old_pe[path_len] = pedge[node];
            old_tp[path_len] = to_parent[node];
            ++path_len;
            if (node == leave_node) break;
        }
        parent[new_root] = new_parent;
        pedge[new_root] = enter;
        to_parent[new_root] = new_tp;
        for (int t = 1; t < path_len; ++t) {
            int node = path[t];
            parent[node] = path[t - 1];
            pedge[node] = old_pe[t - 1];
            to_parent[node] = (old_tp[t - 1] == 1) ? -1 : 1;
        }

        // children among subtree. clear only touched heads: new_root and path nodes and old parents.
        // safest small clear: only nodes that are in subtree can be parents of subtree nodes.
        for (int t = 0; t < sub_count; ++t) child_head[order[t]] = -1;
        child_head[new_parent] = child_head[new_parent]; // no-op, new_parent not in subtree
        for (int t = 0; t < sub_count; ++t) {
            int node = order[t];
            if (node == new_root) continue;
            int p = parent[node];
            child_next[node] = child_head[p];
            child_head[p] = node;
        }

        // pi/depth of new_root
        {
            int e = pedge[new_root];
            if (to_parent[new_root] == 1) pi[new_root] = pi[new_parent] + cost[e];
            else pi[new_root] = pi[new_parent] - cost[e];
            depth[new_root] = depth[new_parent] + 1;
        }

        // DFS preorder
        int sptr = 0, idx = 0;
        stackv[sptr++] = new_root;
        // reuse path buffer as preorder output? use a second pass into order after saving nodes.
        // sub nodes currently in order[0..sub_count). DFS writes into path[0..] then copy.
        while (sptr) {
            int node = stackv[--sptr];
            path[idx++] = node;
            // push children, set their depth/pi
            // children linked list; push so we need reverse. collect into old_pe scratch
            int ccount = 0;
            for (int c = child_head[node]; c >= 0; c = child_next[c]) old_pe[ccount++] = c;
            for (int t = 0; t < ccount; ++t) {
                int c = old_pe[t];
                depth[c] = depth[node] + 1;
                int e = pedge[c];
                if (to_parent[c] == 1) pi[c] = pi[node] + cost[e];
                else pi[c] = pi[node] - cost[e];
            }
            for (int t = ccount - 1; t >= 0; --t) stackv[sptr++] = old_pe[t];
        }

        int old_next = thread[new_parent];
        thread[new_parent] = path[0];
        rev[path[0]] = new_parent;
        for (int t = 0; t < sub_count - 1; ++t) {
            thread[path[t]] = path[t + 1];
            rev[path[t + 1]] = path[t];
        }
        thread[path[sub_count - 1]] = old_next;
        rev[old_next] = path[sub_count - 1];
    };

    for (int it = 0; it < max_iter; ++it) {
        // pricing: first negative in a rotating scan, but keep scanning a small block for a good one
        double best = -tol;
        int enter = -1;
        int e = next_start;
        int scanned = 0;
        const int block = 512;
        while (scanned < Ereal) {
            double red = cost[e] - pi[tail[e]] + pi[hed[e]];
            if (red < best) {
                best = red;
                enter = e;
                if (best < -1e-6 && scanned > 64) break; // good enough candidate
            }
            ++scanned;
            if (enter >= 0 && scanned >= block) break;
            if (++e == Ereal) e = 0;
        }
        next_start = (e + 1) % Ereal;
        if (enter < 0) { iters = it; break; }

        int u = tail[enter], v = hed[enter];
        int uu = u, vv = v;
        while (depth[uu] > depth[vv]) uu = parent[uu];
        while (depth[vv] > depth[uu]) vv = parent[vv];
        while (uu != vv) { uu = parent[uu]; vv = parent[vv]; }
        int apex = uu;

        double delta = 1e100;
        int leave_node = -1, leave_side = -1;
        for (int node = u; node != apex; node = parent[node]) {
            if (to_parent[node] == 1) {
                double f = flow[pedge[node]];
                if (f < delta) { delta = f; leave_node = node; leave_side = 0; }
            }
        }
        for (int node = v; node != apex; node = parent[node]) {
            if (to_parent[node] == -1) {
                double f = flow[pedge[node]];
                if (f <= delta) { delta = f; leave_node = node; leave_side = 1; }
            }
        }
        if (leave_node < 0) break;

        flow[enter] += delta;
        for (int node = u; node != apex; node = parent[node]) {
            int pe = pedge[node];
            if (to_parent[node] == 1) flow[pe] -= delta; else flow[pe] += delta;
        }
        for (int node = v; node != apex; node = parent[node]) {
            int pe = pedge[node];
            if (to_parent[node] == -1) flow[pe] -= delta; else flow[pe] += delta;
        }
        piv(enter, u, v, leave_node, leave_side);
        iters = it + 1;
    }

    double art = 0;
    for (int e = Ereal; e < ET; ++e) art += flow[e];
    std::memcpy(flow_out, flow.data(), Ereal * sizeof(double));
    return Result{iters, art};
}
