import ctypes, numpy as np, time, ot
lib = ctypes.CDLL('./libsimplex2.so')
class Result(ctypes.Structure):
    _fields_ = [('iters', ctypes.c_int), ('art_flow', ctypes.c_double)]
lib.solve_ot.restype = Result
lib.solve_ot.argtypes = [ctypes.POINTER(ctypes.c_double)]*2 + [ctypes.c_int, ctypes.c_int, ctypes.POINTER(ctypes.c_int), ctypes.POINTER(ctypes.c_int), ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.c_int]

def solve(a, rows, cols, data):
    n=len(a); E=len(rows)
    flow=np.zeros(E)
    r=lib.solve_ot(a.ctypes.data_as(ctypes.POINTER(ctypes.c_double)), a.ctypes.data_as(ctypes.POINTER(ctypes.c_double)), n, n,
        rows.ctypes.data_as(ctypes.POINTER(ctypes.c_int)), cols.ctypes.data_as(ctypes.POINTER(ctypes.c_int)),
        data.ctypes.data_as(ctypes.POINTER(ctypes.c_double)), E, flow.ctypes.data_as(ctypes.POINTER(ctypes.c_double)), 1000000)
    return flow, r.art_flow, r.iters

def cand(M,k):
    n=M.shape[0]
    idx=np.argpartition(M,k-1,axis=1)[:,:k]
    rows=np.repeat(np.arange(n),k).astype(np.int32)
    cols=idx.reshape(-1).astype(np.int32)
    return rows, cols, np.ascontiguousarray(M[rows,cols])

n=600
a=np.ascontiguousarray(np.ones(n)/n)
times=[]; worst=0
for seed in range(8):
    np.random.seed(seed)
    sp=np.random.rand(n,2); tp=np.random.rand(n,2)
    M=np.ascontiguousarray(ot.dist(sp,tp),dtype=np.float64)
    G=ot.lp.emd(a,a,M,check_marginals=False)
    t0=time.perf_counter()
    rows,cols,data=cand(M,40)
    flow,art,it=solve(a,rows,cols,data)
    dt=time.perf_counter()-t0
    Gs=np.zeros((n,n)); mask=flow>1e-15
    Gs[rows[mask], cols[mask]]=flow[mask]
    md=np.max(np.abs(Gs-G)); worst=max(worst,md); times.append(dt)
    print(f'seed {seed} {dt:.4f} iters {it} art {art:.1e} md {md:.1e}')
print('avg', np.mean(times), 'speedup', 0.045/np.mean(times), 'worst', worst)
