// Successive shortest paths with potentials + Dijkstra (dial/binary heap via std::priority_queue)
// for the assignment-equivalent transportation problem with uniform supply 1 (we scale by 1/n outside).
// Supplies are equal a[i]=b[j]=1/n, so we solve integer assignment of unit supplies and scale.
#include <cstdint>
#include <vector>
#include <queue>
#include <cmath>
#include <cstring>
#include <algorithm>

struct Result { int augments; double art; };

extern "C" Result solve_assign(int n, const int* edge_i, const int* edge_j, const double* edge_c, int E,
                               int* match_out) {
    // match_out[i] = column assigned to row i, or -1
    // Graph residual: sources 0..n-1, sinks n..2n-1
    // We don't use super source; we augment from each unmatched source to any unmatched sink.
    const int N = 2 * n;
    const double INF = 1e100;

    // adjacency: each real edge has forward + reverse. Also we may add nothing else.
    int E2 = E * 2;
    std::vector<int> head(N, -1), to(E2), nxt(E2), rev(E2);
    std::vector<double> cost(E2), cap(E2);
    int ec = 0;
    auto add_edge = [&](int u, int v, double c, double capacity) {
        to[ec] = v; nxt[ec] = head[u]; cost[ec] = c; cap[ec] = capacity; rev[ec] = ec + 1; head[u] = ec; ++ec;
        to[ec] = u; nxt[ec] = head[v]; cost[ec] = -c; cap[ec] = 0; rev[ec] = ec - 1; head[v] = ec; ++ec;
    };
    for (int e = 0; e < E; ++e) add_edge(edge_i[e], n + edge_j[e], edge_c[e], 1.0);

    std::vector<double> pot(N, 0.0), dist(N);
    std::vector<int> prev_e(N), prev_u(N);
    std::vector<char> matched_sink(n, 0);
    int augments = 0;

    using P = std::pair<double, int>;
    for (int src = 0; src < n; ++src) {
        std::fill(dist.begin(), dist.end(), INF);
        std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
        dist[src] = 0;
        pq.push({0, src});
        int target = -1;
        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (d > dist[u]) continue;
            if (u >= n && !matched_sink[u - n]) { target = u; break; }
            for (int e = head[u]; e != -1; e = nxt[e]) {
                if (cap[e] < 0.5) continue;
                int v = to[e];
                double nd = d + cost[e] + pot[u] - pot[v];
                if (nd < dist[v]) {
                    dist[v] = nd;
                    prev_e[v] = e;
                    prev_u[v] = u;
                    pq.push({nd, v});
                }
            }
        }
        if (target < 0) {
            // infeasible candidate graph
            for (int i = 0; i < n; ++i) match_out[i] = -1;
            return Result{augments, 1.0};
        }
        for (int i = 0; i < N; ++i) if (dist[i] < INF/2) pot[i] += dist[i];
        // augment unit
        for (int v = target; v != src; v = prev_u[v]) {
            int e = prev_e[v];
            cap[e] -= 1;
            cap[rev[e]] += 1;
        }
        matched_sink[target - n] = 1;
        ++augments;
    }
    // read matching: for each source, the forward edge with cap 0 (used)
    for (int i = 0; i < n; ++i) match_out[i] = -1;
    for (int e = 0; e < E; ++e) {
        int fwd = e * 2;
        if (cap[fwd] < 0.5) {
            match_out[edge_i[e]] = edge_j[e];
        }
    }
    return Result{augments, 0.0};
}
