c++ -O3 -std=c++17 -shared -fPIC ssp.cpp -o libssp.so && python3 - << 'PY'
import ctypes, numpy as np, time, ot
lib=ctypes.CDLL('./libssp.so')
class Result(ctypes.Structure):
    _fields_=[('augments', ctypes.c_int), ('art', ctypes.c_double)]
lib.solve_assign.restype=Result
lib.solve_assign.argtypes=[ctypes.c_int, ctypes.POINTER(ctypes.c_int), ctypes.POINTER(ctypes.c_int), ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_int)]

def cand(M,k):
    n=M.shape[0]
    idx=np.argpartition(M,k-1,axis=1)[:,:k]
    rows=np.repeat(np.arange(n),k).astype(np.int32)
    cols=idx.reshape(-1).astype(np.int32)
    return rows, cols, np.ascontiguousarray(M[rows,cols])

def solve(rows, cols, data, n):
    match=np.full(n, -1, np.int32)
    r=lib.solve_assign(n, rows.ctypes.data_as(ctypes.POINTER(ctypes.c_int)), cols.ctypes.data_as(ctypes.POINTER(ctypes.c_int)),
                       data.ctypes.data_as(ctypes.POINTER(ctypes.c_double)), len(rows), match.ctypes.data_as(ctypes.POINTER(ctypes.c_int)))
    return match, r.augments, r.art

n=600
a=np.ones(n)/n
times=[]; worst=0; fails=0
for seed in range(6):
    np.random.seed(seed)
    sp=np.random.rand(n,2); tp=np.random.rand(n,2)
    M=np.ascontiguousarray(ot.dist(sp,tp),dtype=np.float64)
    G=ot.lp.emd(a,a,M,check_marginals=False)
    t0=time.perf_counter()
    rows,cols,data=cand(M,40)
    match,aug,art=solve(rows,cols,data,n)
    dt=time.perf_counter()-t0
    Gs=np.zeros((n,n))
    if art==0 and np.all(match>=0):
        Gs[np.arange(n), match]=1.0/n
        md=np.max(np.abs(Gs-G))
    else:
        md=1; fails+=1
    worst=max(worst,md); times.append(dt)
    print(f'seed {seed} {dt:.4f} aug {aug} art {art:.1e} md {md:.1e}')
print('avg', np.mean(times), 'speedup', 0.045/np.mean(times), 'worst', worst, 'fails', fails)
PY"}

