#include <cstdint>
#include <vector>
#include <cmath>
#include <cstring>
#include <algorithm>

// Jonker-Volgenant shortest augmenting path for dense square assignment.
// Returns col_of_row[i].
extern "C" void lapjv(const double* C, int n, int* col_of_row) {
    const double INF = 1e100;
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> row_of_col(n, -1), col_of_row_v(n, -1);
    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<char> seen(n);

    for (int i = 0; i < n; ++i) {
        // start augmentation from row i
        int jcur = -1;
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(seen.begin(), seen.end(), 0);
        std::fill(pred.begin(), pred.end(), -1);
        int sink = -1;
        // Dijkstra over columns
        // initialize with edges from row i
        for (int j = 0; j < n; ++j) {
            dist[j] = C[(size_t)i * n + j] - u[i] - v[j];
            pred[j] = i;
        }
        while (true) {
            int jmin = -1;
            double dmin = INF;
            for (int j = 0; j < n; ++j) if (!seen[j] && dist[j] < dmin) { dmin = dist[j]; jmin = j; }
            if (jmin < 0) break;
            seen[jmin] = 1;
            if (row_of_col[jmin] < 0) { sink = jmin; break; }
            // update dual-ish distances through the matched row
            int i2 = row_of_col[jmin];
            double ui = u[i2]; // not yet updated; use reduced
            for (int j = 0; j < n; ++j) if (!seen[j]) {
                double nd = dmin + C[(size_t)i2 * n + j] - u[i2] - v[j] - (C[(size_t)i2 * n + jmin] - u[i2] - v[jmin]);
                // simplified: slack from matched row
                // standard: dist[j] = min(dist[j], dmin + C[i2,j] - u[i2] - v[j] - (something already in dmin))
                // The reduced cost of (i2,j) relative to (i2,jmin):
                nd = dmin + (C[(size_t)i2 * n + j] - v[j]) - (C[(size_t)i2 * n + jmin] - v[jmin]);
                if (nd < dist[j]) { dist[j] = nd; pred[j] = i2; }
            }
        }
        // update duals
        // u[i] and v along the path. Classic:
        // for visited columns, v[j] += dist[j] - dist[sink]; for their matched rows u -= ...
        double dsink = dist[sink];
        for (int j = 0; j < n; ++j) if (seen[j]) {
            v[j] += dist[j] - dsink;
            if (row_of_col[j] >= 0) u[row_of_col[j]] -= dist[j] - dsink;
        }
        u[i] += dsink; // row i reduced cost adjustment? 
        // augment
        int j = sink;
        while (j >= 0) {
            int i2 = pred[j];
            int jprev = (i2 == i) ? -1 : col_of_row_v[i2];
            row_of_col[j] = i2;
            col_of_row_v[i2] = j;
            j = jprev;
        }
    }
    for (int i = 0; i < n; ++i) col_of_row[i] = col_of_row_v[i];
}
