import ctypes, numpy as np, time
from scipy.optimize import linear_sum_assignment
lib=ctypes.CDLL('./libhung.so')
lib.lapjv.argtypes=[ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_int)]

def lap(M):
    n=M.shape[0]
    col=np.empty(n, np.int32)
    lib.lapjv(np.ascontiguousarray(M,dtype=np.float64).ctypes.data_as(ctypes.POINTER(ctypes.c_double)), n, col.ctypes.data_as(ctypes.POINTER(ctypes.c_int)))
    return col

for n in [50, 100, 200]:
    np.random.seed(0)
    M=np.random.rand(n,n)
    t0=time.perf_counter(); c=lap(M); t=time.perf_counter()-t0
    r,cs=linear_sum_assignment(M)
    print(n, 'time', t, 'cost_eq', abs(M[np.arange(n),c].sum()-M[r,cs].sum())<1e-6, 'perm', np.array_equal(c,cs))
