#include <cstdint>
#include <vector>
#include <cmath>
#include <cstring>
#include <algorithm>

struct Result { int augments; double art; };

// Sparse assignment via successive shortest paths + potentials.
// Dijkstra uses a simple O(N^2) scan which is fine because N=1200 and the graph is sparse,
// but we use adjacency so each scan only follows existing edges... O(N^2) scan of nodes is 1200^2 * 600 = too slow.
// Use dial? Binary heap via pairing heap handrolled: a binary heap on vectors.
extern "C" Result solve_assign(int n, const int* edge_i, const int* edge_j, const double* edge_c, int E, int* match_out) {
    const int N = 2 * n;
    const double INF = 1e100;
    std::vector<int> head(N, -1), to, nxt, rev;
    std::vector<double> cost, cap;
    to.reserve(E*2); nxt.reserve(E*2); rev.reserve(E*2); cost.reserve(E*2); cap.reserve(E*2);
    auto add = [&](int u, int v, double c, double cp) {
        int e = (int)to.size();
        to.push_back(v); nxt.push_back(head[u]); cost.push_back(c); cap.push_back(cp); rev.push_back(e+1); head[u]=e;
        to.push_back(u); nxt.push_back(head[v]); cost.push_back(-c); cap.push_back(0); rev.push_back(e); head[v]=e+1;
    };
    for (int e = 0; e < E; ++e) add(edge_i[e], n + edge_j[e], edge_c[e], 1.0);

    std::vector<double> pot(N, 0.0), dist(N);
    std::vector<int> prev_e(N), prev_u(N);
    std::vector<char> sink_matched(n, 0);

    // binary heap
    std::vector<int> heap;
    std::vector<int> pos(N, -1);
    auto hswap = [&](int i, int j) {
        std::swap(heap[i], heap[j]);
        pos[heap[i]] = i; pos[heap[j]] = j;
    };
    auto sift_up = [&](int i) {
        while (i > 0) {
            int p = (i - 1) / 2;
            if (dist[heap[p]] <= dist[heap[i]]) break;
            hswap(i, p); i = p;
        }
    };
    auto sift_down = [&](int i) {
        int hs = (int)heap.size();
        while (true) {
            int l = 2*i+1, r = l+1, b = i;
            if (l < hs && dist[heap[l]] < dist[heap[b]]) b = l;
            if (r < hs && dist[heap[r]] < dist[heap[b]]) b = r;
            if (b == i) break;
            hswap(i, b); i = b;
        }
    };
    auto push = [&](int u) {
        if (pos[u] >= 0) { sift_up(pos[u]); return; }
        pos[u] = (int)heap.size();
        heap.push_back(u);
        sift_up(pos[u]);
    };
    auto pop = [&]() {
        int u = heap[0];
        int last = heap.back(); heap.pop_back();
        pos[u] = -1;
        if (!heap.empty()) { heap[0] = last; pos[last] = 0; sift_down(0); }
        return u;
    };

    int augments = 0;
    for (int src = 0; src < n; ++src) {
        std::fill(dist.begin(), dist.end(), INF);
        heap.clear();
        std::fill(pos.begin(), pos.end(), -1);
        dist[src] = 0;
        push(src);
        int target = -1;
        while (!heap.empty()) {
            int u = pop();
            if (u >= n && !sink_matched[u - n]) { target = u; break; }
            double du = dist[u];
            for (int e = head[u]; e != -1; e = nxt[e]) {
                if (cap[e] < 0.5) continue;
                int v = to[e];
                double nd = du + cost[e] + pot[u] - pot[v];
                if (nd < dist[v]) {
                    dist[v] = nd;
                    prev_e[v] = e;
                    prev_u[v] = u;
                    push(v);
                }
            }
        }
        if (target < 0) {
            for (int i = 0; i < n; ++i) match_out[i] = -1;
            return Result{augments, 1.0};
        }
        for (int i = 0; i < N; ++i) if (dist[i] < INF/2) pot[i] += dist[i];
        for (int v = target; v != src; v = prev_u[v]) {
            int e = prev_e[v];
            cap[e] -= 1; cap[rev[e]] += 1;
        }
        sink_matched[target - n] = 1;
        ++augments;
    }
    for (int i = 0; i < n; ++i) match_out[i] = -1;
    // forward edges are even indices 0,2,4,... corresponding to input order
    for (int e = 0; e < E; ++e) {
        if (cap[e * 2] < 0.5) match_out[edge_i[e]] = edge_j[e];
    }
    return Result{augments, 0.0};
}
