{"command":"cat > auction.cpp << 'EOF'
#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstring>

// Sparse epsilon-scaling auction for min-cost assignment.
// Returns 0 on success, 1 if iteration limit hit.
extern "C" int auction_assign(int n, const int* edge_i, const int* edge_j, const double* edge_c, int E,
                              int* match_out, int max_bids) {
    // build adjacency: for each row, list of (col, cost)
    std::vector<std::vector<std::pair<int,double>>> adj(n);
    for (int e = 0; e < E; ++e) adj[edge_i[e]].emplace_back(edge_j[e], edge_c[e]);

    double cmax = 0;
    for (int e = 0; e < E; ++e) if (edge_c[e] > cmax) cmax = edge_c[e];
    if (cmax < 1e-12) cmax = 1e-12;

    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);      // owner[col] = row
    std::vector<int> match(n, -1);      // match[row] = col

    double eps = cmax / 4.0;
    const double eps_final = 1e-12;
    int bids = 0;

    while (eps >= eps_final) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(match.begin(), match.end(), -1);
        // queue of unassigned
        std::vector<int> unassigned(n);
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int uq = n;

        bool failed = false;
        while (uq > 0) {
            if (++bids > max_bids) { failed = true; break; }
            int i = unassigned[--uq];
            const auto& nbrs = adj[i];
            int nn = (int)nbrs.size();
            if (nn == 0) { failed = true; break; }
            // best and second best value = -cost - price
            double best = -1e300, second = -1e300;
            int bestj = nbrs[0].first;
            for (int t = 0; t < nn; ++t) {
                double val = -nbrs[t].second - price[nbrs[t].first];
                if (val > best) { second = best; best = val; bestj = nbrs[t].first; }
                else if (val > second) second = val;
            }
            if (second < -1e299) second = best - 1.0; // only one neighbor
            // bid increment so that best becomes equal to second - eps (in value), i.e. raise price
            // new price = price + (best - second) + eps
            double raise = (best - second) + eps;
            price[bestj] += raise;
            int prev = owner[bestj];
            if (prev >= 0) {
                match[prev] = -1;
                unassigned[uq++] = prev;
            }
            owner[bestj] = i;
            match[i] = bestj;
        }
        if (failed) {
            for (int i = 0; i < n; ++i) match_out[i] = -1;
            return 1;
        }
        eps *= 0.25;
    }
    for (int i = 0; i < n; ++i) match_out[i] = match[i];
    return 0;
}
