{"command":"cat > auction2.cpp << 'EOF'
#include <cstdint>
#include <vector>
#include <algorithm>
#include <cmath>

// Forward-reverse auction (Bertsekas) for sparse min-cost assignment, epsilon scaling.
// Works on a bipartite graph that must contain an optimal assignment.
extern "C" int fra_assign(int n, const int* edge_i, const int* edge_j, const double* edge_c, int E,
                          int* match_out, int max_iter) {
    std::vector<std::vector<std::pair<int,double>>> adj(n);
    for (int e = 0; e < E; ++e) adj[edge_i[e]].emplace_back(edge_j[e], edge_c[e]);

    double cmax = 0;
    for (int e = 0; e < E; ++e) cmax = std::max(cmax, edge_c[e]);
    if (cmax < 1e-12) cmax = 1.0;

    std::vector<double> price(n, 0.0);     // column prices
    std::vector<double> profit(n, 0.0);    // row profits (dual)
    std::vector<int> owner(n, -1);
    std::vector<int> match(n, -1);

    // epsilon scaling
    double eps = cmax / 2.0;
    int iters = 0;
    while (eps > 1e-12) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(match.begin(), match.end(), -1);
        std::vector<int> unassigned;
        unassigned.reserve(n);
        for (int i = 0; i < n; ++i) unassigned.push_back(i);

        bool failed = false;
        while (!unassigned.empty()) {
            if (++iters > max_iter) { failed = true; break; }
            int i = unassigned.back(); unassigned.pop_back();
            auto& nbrs = adj[i];
            int nn = (int)nbrs.size();
            if (nn == 0) { failed = true; break; }

            double best = -1e300, second = -1e300;
            int bestj = nbrs[0].first;
            for (int t = 0; t < nn; ++t) {
                double val = -nbrs[t].second - price[nbrs[t].first];
                if (val > best) { second = best; best = val; bestj = nbrs[t].first; }
                else if (val > second) second = val;
            }
            if (!(second > -1e299)) second = best - eps;

            // forward bid
            double bid = price[bestj] + (best - second) + eps;
            profit[i] = best - eps; // not strictly needed
            price[bestj] = bid;
            int prev = owner[bestj];
            if (prev >= 0) {
                match[prev] = -1;
                unassigned.push_back(prev);
            }
            owner[bestj] = i;
            match[i] = bestj;
        }
        if (failed) {
            for (int i = 0; i < n; ++i) match_out[i] = -1;
            return 1;
        }
        eps *= 0.2;
    }
    for (int i = 0; i < n; ++i) match_out[i] = match[i];
    return 0;
}
