#include <cstdint>
#include <vector>
#include <algorithm>
#include <cmath>

// Gauss-Seidel auction: prices persist across epsilon scales. Only unassigned rows bid.
// At each scale, rows whose current assignment is still epsilon-optimal keep it.
extern "C" int gs_auction(int n, const int* edge_i, const int* edge_j, const double* edge_c, int E,
                          int* match_out, int max_iter) {
    std::vector<std::vector<std::pair<int,double>>> adj(n);
    adj.reserve(n);
    for (int e = 0; e < E; ++e) adj[edge_i[e]].emplace_back(edge_j[e], edge_c[e]);

    double cmax = 0;
    for (int e = 0; e < E; ++e) cmax = std::max(cmax, edge_c[e]);
    if (cmax < 1e-12) cmax = 1.0;

    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> match(n, -1);

    double eps = cmax / 2.0;
    int iters = 0;

    auto best_two = [&](int i, double& best, double& second, int& bestj) {
        best = -1e300; second = -1e300; bestj = -1;
        for (auto& pr : adj[i]) {
            double val = -pr.second - price[pr.first];
            if (val > best) { second = best; best = val; bestj = pr.first; }
            else if (val > second) second = val;
        }
        if (bestj < 0) return false;
        if (!(second > -1e299)) second = best - eps;
        return true;
    };

    while (eps > 1e-12) {
        // mark rows that are no longer eps-happy as unassigned
        std::vector<int> unassigned;
        unassigned.reserve(n);
        for (int i = 0; i < n; ++i) {
            double best, second; int bestj;
            if (!best_two(i, best, second, bestj)) { for (int k=0;k<n;k++) match_out[k]=-1; return 1; }
            int cur = match[i];
            bool happy = false;
            if (cur >= 0 && owner[cur] == i) {
                // value of current
                double curv = -1e300;
                for (auto& pr : adj[i]) if (pr.first == cur) { curv = -pr.second - price[cur]; break; }
                // happy if within eps of best
                if (curv >= best - eps) happy = true;
            }
            if (!happy) {
                if (cur >= 0 && owner[cur] == i) { owner[cur] = -1; match[i] = -1; }
                unassigned.push_back(i);
            }
        }
        bool failed = false;
        while (!unassigned.empty()) {
            if (++iters > max_iter) { failed = true; break; }
            int i = unassigned.back(); unassigned.pop_back();
            double best, second; int bestj;
            if (!best_two(i, best, second, bestj)) { failed = true; break; }
            price[bestj] += (best - second) + eps;
            int prev = owner[bestj];
            if (prev >= 0) {
                match[prev] = -1;
                unassigned.push_back(prev);
            }
            owner[bestj] = i;
            match[i] = bestj;
        }
        if (failed) { for (int k=0;k<n;k++) match_out[k]=-1; return 1; }
        eps *= 0.25;
    }
    for (int i = 0; i < n; ++i) match_out[i] = match[i];
    return 0;
}
