#include <cstdint>
#include <vector>
#include <algorithm>
#include <cmath>
#include <cstring>

// Given source/target points (n x 2) and the cost matrix M (n x n, row-major) which is sqeuclidean,
// find k nearest targets per source using squared distance computed on the fly (no M read for selection),
// then run auction using costs looked up from M so the plan matches emd exactly.
// Returns match[i] = column.

static int auction(int n, const std::vector<int>& ei, const std::vector<int>& ej, const std::vector<double>& ec,
                   int* match_out, int max_iter) {
    std::vector<std::vector<std::pair<int,double>>> adj(n);
    int E = (int)ei.size();
    for (int e = 0; e < E; ++e) adj[ei[e]].emplace_back(ej[e], ec[e]);
    double cmax = 0;
    for (double c : ec) if (c > cmax) cmax = c;
    if (cmax < 1e-12) cmax = 1e-12;
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), match(n, -1);
    double eps = cmax / 4.0;
    int bids = 0;
    while (eps >= 1e-12) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(match.begin(), match.end(), -1);
        std::vector<int> ua(n);
        for (int i = 0; i < n; ++i) ua[i] = i;
        int uq = n;
        bool failed = false;
        while (uq > 0) {
            if (++bids > max_iter) { failed = true; break; }
            int i = ua[--uq];
            auto& nbrs = adj[i];
            int nn = (int)nbrs.size();
            if (!nn) { failed = true; break; }
            double best = -1e300, second = -1e300;
            int bestj = nbrs[0].first;
            for (int t = 0; t < nn; ++t) {
                double val = -nbrs[t].second - price[nbrs[t].first];
                if (val > best) { second = best; best = val; bestj = nbrs[t].first; }
                else if (val > second) second = val;
            }
            if (!(second > -1e299)) second = best - 1.0;
            price[bestj] += (best - second) + eps;
            int prev = owner[bestj];
            if (prev >= 0) { match[prev] = -1; ua[uq++] = prev; }
            owner[bestj] = i;
            match[i] = bestj;
        }
        if (failed) { for (int i=0;i<n;i++) match_out[i]=-1; return 1; }
        eps *= 0.25;
    }
    for (int i = 0; i < n; ++i) match_out[i] = match[i];
    return 0;
}

extern "C" int solve_from_points(int n, const double* sp, const double* tp, const double* M, int k, int* match_out) {
    // k nearest by squared euclidean, costs from M
    std::vector<int> ei; ei.reserve((size_t)n * k);
    std::vector<int> ej; ej.reserve((size_t)n * k);
    std::vector<double> ec; ec.reserve((size_t)n * k);
    std::vector<double> dist(n);
    std::vector<int> idx(n);
    for (int i = 0; i < n; ++i) {
        double sx = sp[2*i], sy = sp[2*i+1];
        for (int j = 0; j < n; ++j) {
            double dx = sx - tp[2*j], dy = sy - tp[2*j+1];
            dist[j] = dx*dx + dy*dy;
            idx[j] = j;
        }
        // partial select k smallest
        std::nth_element(idx.begin(), idx.begin() + (k - 1), idx.end(), [&](int a, int b){ return dist[a] < dist[b]; });
        for (int t = 0; t < k; ++t) {
            int j = idx[t];
            ei.push_back(i);
            ej.push_back(j);
            ec.push_back(M[(size_t)i * n + j]);
        }
    }
    return auction(n, ei, ej, ec, match_out, 20000000);
}
