// Cost-scaling assignment (push-relabel style) for sparse bipartite min-cost perfect matching.
// Unit capacities, unit supplies. Based on the cost-scaling algorithm:
// maintain epsilon-optimality of reduced costs, refine epsilon, push/relabel.
#include <cstdint>
#include <vector>
#include <algorithm>
#include <cmath>
#include <cstring>

struct Result { int ok; int pushes; };

extern "C" Result cost_scale(int n, const int* edge_i, const int* edge_j, const double* edge_c, int E, int* match_out) {
    // Nodes: sources 0..n-1, sinks n..2n-1
    const int N = 2 * n;
    const double INF = 1e100;
    int E2max = E * 2 + 4 * n; // residual edges + possible? we only have given edges
    std::vector<int> head(N, -1), to, nxt, rev;
    std::vector<double> cost, cap;
    to.reserve(E*2); nxt.reserve(E*2); cost.reserve(E*2); cap.reserve(E*2); rev.reserve(E*2);
    auto add = [&](int u, int v, double c) {
        int e = (int)to.size();
        to.push_back(v); nxt.push_back(head[u]); cost.push_back(c); cap.push_back(1); rev.push_back(e+1); head[u]=e;
        to.push_back(u); nxt.push_back(head[v]); cost.push_back(-c); cap.push_back(0); rev.push_back(e); head[v]=e+1;
    };
    for (int e = 0; e < E; ++e) add(edge_i[e], n + edge_j[e], edge_c[e]);

    std::vector<double> pot(N, 0.0);
    std::vector<double> excess(N, 0.0);
    for (int i = 0; i < n; ++i) excess[i] = 1.0;
    for (int j = 0; j < n; ++j) excess[n+j] = -1.0;

    double C = 0;
    for (int e = 0; e < E; ++e) C = std::max(C, std::abs(edge_c[e]));
    if (C < 1e-12) C = 1e-12;
    double eps = C;
    int pushes = 0;

    auto admissible = [&](int u, int e) {
        int v = to[e];
        return cap[e] > 0.5 && cost[e] + pot[u] - pot[v] < -1e-15;
    };

    // refine
    int guard = 0;
    while (eps > 1e-11) {
        eps *= 0.5;
        // saturate admissible edges (push as much as possible along negative reduced cost)
        // then relabel nodes with excess until no positive excess on sources / deficit handled.
        // Standard: while some node has excess > 0, if it has admissible edge push, else relabel.
        // Sinks with deficit (excess < 0) are targets. Sources start with excess 1.
        // A feasible push reduces excess. We allow pushes to sinks (which have negative excess target of -1,
        // meaning they want 1 unit). Excess of sink starts at -1 and should end at 0.
        // Only nodes with excess > 0 push.
        std::vector<int> active;
        active.reserve(n);
        for (int i = 0; i < N; ++i) if (excess[i] > 0.5) active.push_back(i);

        int iter = 0;
        const int ITERMAX = 2000000;
        while (!active.empty()) {
            if (++iter > ITERMAX || ++guard > 20000000) {
                for (int i = 0; i < n; ++i) match_out[i] = -1;
                return Result{0, pushes};
            }
            int u = active.back();
            if (excess[u] <= 0.5) { active.pop_back(); continue; }
            // find admissible edge
            int best = -1;
            for (int e = head[u]; e != -1; e = nxt[e]) {
                if (cap[e] > 0.5 && cost[e] + pot[u] - pot[to[e]] < -eps + 1e-15) {
                    best = e; break;
                }
            }
            if (best >= 0) {
                int v = to[best];
                cap[best] -= 1; cap[rev[best]] += 1;
                excess[u] -= 1; excess[v] += 1;
                ++pushes;
                if (excess[v] > 0.5) active.push_back(v);
            } else {
                // relabel: pot[u] = min over residual edges of pot[v] - cost[e] - eps? 
                // to restore eps-optimality, set pot[u] so the best residual edge has reduced cost = -eps? 
                // reduced = cost + pot[u] - pot[v]. We want min reduced = 0 after relabel? For eps-optimality
                // reduced >= -eps. Set pot[u] = min_v (pot[v] - cost[e]) - eps, so min reduced = -eps.
                double mn = INF;
                bool any = false;
                for (int e = head[u]; e != -1; e = nxt[e]) if (cap[e] > 0.5) {
                    any = true;
                    double val = pot[to[e]] - cost[e];
                    if (val < mn) mn = val;
                }
                if (!any) {
                    for (int i = 0; i < n; ++i) match_out[i] = -1;
                    return Result{0, pushes};
                }
                pot[u] = mn - eps;
            }
        }
    }
    // read matching: forward edges with cap 0
    for (int i = 0; i < n; ++i) match_out[i] = -1;
    for (int e = 0; e < E; ++e) {
        // forward edge index is 2*e
        if (cap[2*e] < 0.5) match_out[edge_i[e]] = edge_j[e];
    }
    for (int i = 0; i < n; ++i) if (match_out[i] < 0) return Result{0, pushes};
    return Result{1, pushes};
}
